// signal.ts

type Subscriber = () => void;

let activeSubscriber: Subscriber | null = null;

export type Signal<T> = {
  (): T;
  set(value: T): void;
  update(updater: (value: T) => T): void;
};

export function signal<T>(initialValue: T): Signal<T> {
  let value = initialValue;
  const subscribers = new Set<Subscriber>();

  const read = (() => {
    if (activeSubscriber) {
      subscribers.add(activeSubscriber);
    }

    return value;
  }) as Signal<T>;

  read.set = (nextValue: T) => {
    if (Object.is(value, nextValue)) {
      return;
    }

    value = nextValue;

    for (const subscriber of subscribers) {
      subscriber();
    }
  };

  read.update = (updater) => {
    read.set(updater(value));
  };

  return read;
}

export function computed<T>(compute: () => T): () => T {
  let value: T;
  let initialized = false;
  let dirty = true;

  const recompute = () => {
    dirty = true;
  };

  const read = () => {
    if (!initialized || dirty) {
      const previousSubscriber = activeSubscriber;

      activeSubscriber = recompute;

      try {
        value = compute();
        initialized = true;
        dirty = false;
      } finally {
        activeSubscriber = previousSubscriber;
      }
    }

    return value;
  };

  return read;
}

export function effect(callback: () => void): () => void {
  let active = true;

  const runner = () => {
    if (!active) {
      return;
    }

    const previousSubscriber = activeSubscriber;

    activeSubscriber = runner;

    try {
      callback();
    } finally {
      activeSubscriber = previousSubscriber;
    }
  };

  runner();

  return () => {
    active = false;
  };
}